-- ============================================================
-- Adventure_work Database - Schema Creation Script
-- Star-schema data warehouse for Adventure Works Internet Sales
-- ============================================================

DROP DATABASE IF EXISTS Adventure_work;
CREATE DATABASE Adventure_work
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE Adventure_work;

-- ------------------------------------------------------------
-- DIM: Sales Territory
-- ------------------------------------------------------------
CREATE TABLE DimSalesTerritory (
    SalesTerritoryKey           INT PRIMARY KEY,
    SalesTerritoryAlternateKey  INT,
    SalesTerritoryRegion        VARCHAR(50),
    SalesTerritoryCountry       VARCHAR(50),
    SalesTerritoryGroup         VARCHAR(50)
);

-- ------------------------------------------------------------
-- DIM: Product Category
-- ------------------------------------------------------------
CREATE TABLE DimProductCategory (
    ProductCategoryKey           INT PRIMARY KEY,
    ProductCategoryAlternateKey  INT,
    EnglishProductCategoryName   VARCHAR(50),
    SpanishProductCategoryName   VARCHAR(50),
    FrenchProductCategoryName    VARCHAR(50)
);

-- ------------------------------------------------------------
-- DIM: Product Subcategory
-- ------------------------------------------------------------
CREATE TABLE DimProductSubcategory (
    ProductSubcategoryKey            INT PRIMARY KEY,
    ProductSubcategoryAlternateKey   INT,
    EnglishProductSubcategoryName    VARCHAR(50),
    SpanishProductSubcategoryName    VARCHAR(50),
    FrenchProductSubcategoryName     VARCHAR(50),
    ProductCategoryKey                INT,
    CONSTRAINT fk_subcat_cat FOREIGN KEY (ProductCategoryKey)
        REFERENCES DimProductCategory (ProductCategoryKey)
);

-- ------------------------------------------------------------
-- DIM: Product
-- ------------------------------------------------------------
CREATE TABLE DimProduct (
    ProductKey                 INT PRIMARY KEY,
    UnitPrice                  DECIMAL(10,2),
    ProductAlternateKey        VARCHAR(25),
    ProductSubcategoryKey       INT,
    WeightUnitMeasureCode      VARCHAR(10),
    SizeUnitMeasureCode        VARCHAR(10),
    EnglishProductName         VARCHAR(150),
    SpanishProductName         VARCHAR(150),
    FrenchProductName          VARCHAR(150),
    StandardCost                DECIMAL(10,2),
    FinishedGoodsFlag          TINYINT(1),
    Color                       VARCHAR(30),
    SafetyStockLevel           INT,
    ReorderPoint                INT,
    ListPrice                   DECIMAL(10,2),
    Size                        VARCHAR(10),
    SizeRange                   VARCHAR(20),
    Weight                       DECIMAL(10,2),
    DaysToManufacture           INT,
    ProductLine                 VARCHAR(10),
    DealerPrice                 DECIMAL(10,2),
    Class                       VARCHAR(10),
    Style                       VARCHAR(10),
    ModelName                   VARCHAR(100),
    EnglishDescription           TEXT,
    FrenchDescription            TEXT,
    ChineseDescription            TEXT,
    ArabicDescription             TEXT,
    HebrewDescription             TEXT,
    ThaiDescription                TEXT,
    GermanDescription             TEXT,
    JapaneseDescription           TEXT,
    TurkishDescription            TEXT,
    StartDate                    DATE,
    EndDate                       DATE,
    Status                        VARCHAR(15),
    CONSTRAINT fk_product_subcat FOREIGN KEY (ProductSubcategoryKey)
        REFERENCES DimProductSubcategory (ProductSubcategoryKey)
);

-- ------------------------------------------------------------
-- DIM: Customer
-- ------------------------------------------------------------
CREATE TABLE DimCustomer (
    CustomerKey             INT PRIMARY KEY,
    GeographyKey            INT,
    CustomerAlternateKey    VARCHAR(25),
    Title                   VARCHAR(10),
    FirstName               VARCHAR(50),
    MiddleName              VARCHAR(50),
    LastName                VARCHAR(50),
    NameStyle               TINYINT(1),
    BirthDate               DATE,
    MaritalStatus           VARCHAR(1),
    Suffix                  VARCHAR(10),
    Gender                  VARCHAR(1),
    EmailAddress            VARCHAR(100),
    YearlyIncome            DECIMAL(12,2),
    TotalChildren           INT,
    NumberChildrenAtHome    INT,
    EnglishEducation        VARCHAR(50),
    SpanishEducation        VARCHAR(50),
    FrenchEducation         VARCHAR(50),
    EnglishOccupation       VARCHAR(50),
    SpanishOccupation       VARCHAR(50),
    FrenchOccupation        VARCHAR(50),
    HouseOwnerFlag          TINYINT(1),
    NumberCarsOwned         INT,
    AddressLine1            VARCHAR(120),
    AddressLine2            VARCHAR(120),
    Phone                   VARCHAR(30),
    DateFirstPurchase       DATE,
    CommuteDistance         VARCHAR(20),
    -- Convenience column combining name parts (kept in sync via trigger below)
    CustomerFullName        VARCHAR(150)
);

-- ------------------------------------------------------------
-- DIM: Date
-- ------------------------------------------------------------
CREATE TABLE DimDate (
    DateKey                  INT PRIMARY KEY,
    FullDateAlternateKey     DATE,
    DayNumberOfWeek           INT,
    EnglishDayNameOfWeek     VARCHAR(15),
    SpanishDayNameOfWeek     VARCHAR(15),
    FrenchDayNameOfWeek      VARCHAR(15),
    DayNumberOfMonth          INT,
    DayNumberOfYear           INT,
    WeekNumberOfYear          INT,
    EnglishMonthName         VARCHAR(15),
    SpanishMonthName         VARCHAR(15),
    FrenchMonthName          VARCHAR(15),
    MonthNumberOfYear         INT,
    CalendarQuarter           INT,
    CalendarYear              INT,
    CalendarSemester          INT,
    FiscalQuarter             INT,
    FiscalYear                 INT,
    FiscalSemester             INT
);

-- ------------------------------------------------------------
-- FACT: Internet Sales  (union of FactInternetSales + Fact_Internet_Sales_New)
-- ------------------------------------------------------------
CREATE TABLE FactInternetSales (
    FactSalesKey            BIGINT PRIMARY KEY AUTO_INCREMENT,
    ProductKey               INT,
    OrderDateKey             INT,
    DueDateKey                INT,
    ShipDateKey               INT,
    CustomerKey               INT,
    PromotionKey              INT,
    CurrencyKey               INT,
    SalesTerritoryKey         INT,
    SalesOrderNumber          VARCHAR(25),
    SalesOrderLineNumber      INT,
    RevisionNumber            INT,
    OrderQuantity             INT,
    UnitPrice                 DECIMAL(10,2),
    ExtendedAmount            DECIMAL(12,2),
    UnitPriceDiscountPct      DECIMAL(6,4),
    DiscountAmount            DECIMAL(10,2),
    ProductStandardCost       DECIMAL(10,2),
    TotalProductCost          DECIMAL(12,2),
    SalesAmount               DECIMAL(12,2),
    TaxAmt                    DECIMAL(10,2),
    Freight                   DECIMAL(10,2),
    CarrierTrackingNumber     VARCHAR(50),
    CustomerPONumber          VARCHAR(50),
    OrderDate                 DATE,
    DueDate                    DATE,
    ShipDate                   DATE,
    CONSTRAINT fk_fact_product  FOREIGN KEY (ProductKey)        REFERENCES DimProduct (ProductKey),
    CONSTRAINT fk_fact_customer FOREIGN KEY (CustomerKey)       REFERENCES DimCustomer (CustomerKey),
    CONSTRAINT fk_fact_orderdt  FOREIGN KEY (OrderDateKey)      REFERENCES DimDate (DateKey),
    CONSTRAINT fk_fact_duedt    FOREIGN KEY (DueDateKey)        REFERENCES DimDate (DateKey),
    CONSTRAINT fk_fact_shipdt   FOREIGN KEY (ShipDateKey)       REFERENCES DimDate (DateKey),
    CONSTRAINT fk_fact_territory FOREIGN KEY (SalesTerritoryKey) REFERENCES DimSalesTerritory (SalesTerritoryKey),
    INDEX idx_fact_product (ProductKey),
    INDEX idx_fact_customer (CustomerKey),
    INDEX idx_fact_orderdate (OrderDateKey)
);

-- ============================================================
-- DATA INSERTS (self-contained — no external files needed)
-- ============================================================

SET FOREIGN_KEY_CHECKS = 0;

-- ---------- DimSalesTerritory ----------
-- ---------- DimProductCategory ----------
-- ---------- DimProductSubcategory ----------
-- ---------- DimProduct ----------


-- ---------- DimCustomer ----------





























































