-- ---------- FactInternetSales (union of both fact files) ----------
























































































































-- Backfill convenience full-name column
UPDATE DimCustomer
SET CustomerFullName = TRIM(CONCAT_WS(' ', FirstName, NULLIF(MiddleName,''), LastName));

SET FOREIGN_KEY_CHECKS = 1;

-- Sanity check: row counts per table
SELECT 'DimSalesTerritory' AS TableName, COUNT(*) AS RowCount FROM DimSalesTerritory
UNION ALL SELECT 'DimProductCategory', COUNT(*) FROM DimProductCategory
UNION ALL SELECT 'DimProductSubcategory', COUNT(*) FROM DimProductSubcategory
UNION ALL SELECT 'DimProduct', COUNT(*) FROM DimProduct
UNION ALL SELECT 'DimCustomer', COUNT(*) FROM DimCustomer
UNION ALL SELECT 'DimDate', COUNT(*) FROM DimDate
UNION ALL SELECT 'FactInternetSales', COUNT(*) FROM FactInternetSales;
